style.css:
@-moz-document domain("blognone.com") {
/* 1. ขยายเนื้อหาหลักให้อยู่กึ่งกลาง และกว้างเต็มที่เมื่อซ่อน Sidebar */
    #content,
    .main-content,
    .region-content,
    #main-content {
        width: 100% !important;
        max-width: 950px !important;
        margin: 0 auto !important;
        float: none !important;
    }

    /* 2. ซ่อน Sidebar ไปไว้ด้านขวาของหน้าจอ (Drawer Panel) */
    #sidebar-second,
    aside.sidebar,
    .region-sidebar-second {
        position: fixed !important;
        top: 0 !important;
        right: 0 !important;
        width: 320px !important;
        height: 100vh !important;
        background: #ffffff !important;
        box-shadow: -4px 0 16px rgba(0, 0, 0, 0.15) !important;
        z-index: 99999 !important;
        overflow-y: auto !important;
        padding: 60px 16px 20px 24px !important;
        box-sizing: border-box !important;

        /* ย้ายออกไปนอกจอ โดยให้เหลือแท็บกว้าง 18px โผล่ไว้ */
        transform: translateX(calc(100% - 18px)) !important;
        transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1) !important;
    }

    /* 3. แท็บหรือตัวจับ (Handle) ตรงขอบจอสำหรับบอกตำแหน่ง */
    #sidebar-second::before,
    aside.sidebar::before,
    .region-sidebar-second::before {
        content: "◀" !important;
        position: absolute !important;
        left: 2px !important;
        top: 50% !important;
        transform: translateY(-50%) !important;
        color: #888888 !important;
        font-size: 11px !important;
        pointer-events: none !important;
    }

    /* 4. เมื่อนำเมาส์ไปชี้ (Hover) ที่ขอบขวา แถบจะเลื่อนออกมาอัตโนมัติ */
    #sidebar-second:hover,
    aside.sidebar:hover,
    .region-sidebar-second:hover {
        transform: translateX(0) !important;
    }

    /* (ตัวเลือกเสริม: หากใช้ธีมมืด Dark Mode ให้เปลี่ยนสีพื้นหลังแถบข้าง) */
    /*
    #sidebar-second, aside.sidebar, .region-sidebar-second {
        background: #1e1e1e !important;
        border-left: 1px solid #333 !important;
    }
    */
}
